import React, { useState, useEffect } from 'react';
import { API_BASE_URL } from '@/config/api';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from '@/components/ui/select';
import { toast } from '@/components/ui/sonner';
import { useAuth } from '@/contexts/AuthContext';
import { Checkbox } from '@/components/ui/checkbox';

export default function RumahFormModal({ open, onOpenChange, rumah, onSaved }) {
  const { token } = useAuth();

  const [formData, setFormData] = useState({
    blok_no: '',
    nama_jalan: '',
    pemilik_sah: '',
    jenis_pemilik: 'Milik Sendiri',
    status_penghuni: 'Pemilik',
    sedang_kosong: false,
    aktif: true,
    remark: '',
  });
  const [submitting, setSubmitting] = useState(false);

  // Load rumah data when editing
  useEffect(() => {
    if (rumah) {
      setFormData({
        blok_no: rumah.blok_no || '',
        nama_jalan: rumah.nama_jalan || '',
        pemilik_sah: rumah.pemilik_sah || '',
        jenis_pemilik: rumah.jenis_pemilik || 'Milik Sendiri',
        status_penghuni: rumah.status_penghuni || 'Pemilik',
        sedang_kosong: rumah.sedang_kosong || false,
        aktif: rumah.aktif !== false,
        remark: rumah.remark || '',
      });
    } else {
      setFormData({
        blok_no: '',
        nama_jalan: '',
        pemilik_sah: '',
        jenis_pemilik: 'Milik Sendiri',
        status_penghuni: 'Pemilik',
        sedang_kosong: false,
        aktif: true,
        remark: '',
      });
    }
  }, [rumah, open]);

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setFormData((prev) => ({
      ...prev,
      [name]: value,
    }));
  };

  const handleSelectChange = (name, value) => {
    const finalValue = value === 'none' ? '' : value;
    setFormData((prev) => ({
      ...prev,
      [name]: finalValue,
    }));
  };

  const handleCheckboxChange = (name) => {
    setFormData((prev) => ({
      ...prev,
      [name]: !prev[name],
    }));
  };

  const handleJenisPemilikChange = (value) => {
    setFormData((prev) => {
      const newFormData = { ...prev, jenis_pemilik: value };
      
      // Only auto-set status on create (when rumah is null)
      if (!rumah) {
        if (value === 'Sewa / Kontrak') {
          newFormData.status_penghuni = 'Penghuni Kontrak';
        } else if (value === 'Milik Sendiri') {
          newFormData.status_penghuni = 'Pemilik';
        } else {
          newFormData.status_penghuni = 'Pemilik Tidak Tinggal';
        }
      }
      return newFormData;
    });
  };

  const handleStatusPenguniChange = (value) => {
    const newData = {
      ...formData,
      status_penghuni: value,
    };

    if (value === 'Kosong') {
      newData.sedang_kosong = true;
    }

    setFormData(newData);
  };

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!formData.blok_no.trim()) {
      toast.error('Blok / No Rumah harus diisi');
      return;
    }

    setSubmitting(true);

    try {
      const url = rumah
        ? `${API_BASE_URL}/api/rumah/${rumah.id}`
        : `${API_BASE_URL}/api/rumah`;

      const method = rumah ? 'PUT' : 'POST';

      const response = await fetch(url, {
        method: method,
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${token}`,
        },
        body: JSON.stringify({
          blok_no: formData.blok_no,
          nama_jalan: formData.nama_jalan,
          pemilik_sah: formData.pemilik_sah,
          jenis_pemilik: formData.jenis_pemilik,
          status_penghuni: formData.status_penghuni,
          sedang_kosong: formData.sedang_kosong,
          aktif: formData.aktif,
          remark: formData.remark,
        }),
      });

      if (!response.ok) {
        const error = await response.json();
        throw new Error(error.detail || 'Gagal menyimpan data');
      }

      toast.success(rumah ? 'Data rumah berhasil diperbarui' : 'Data rumah berhasil ditambahkan');
      onOpenChange(false);
      onSaved();
    } catch (error) {
      console.error('Error:', error);
      toast.error(error.message || 'Gagal menyimpan data');
    } finally {
      setSubmitting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl max-h-[90vh] overflow-y-auto dark:bg-gray-900 dark:text-gray-100">
        <DialogHeader>
          <DialogTitle>
            {rumah ? 'Edit Rumah' : 'Tambah Rumah Baru'}
          </DialogTitle>
        </DialogHeader>

        <form onSubmit={handleSubmit} className="space-y-6 py-4">
          {/* Row 1: Blok No & Nama Jalan */}
          <div className="grid grid-cols-2 gap-4">
            <div className="flex flex-col gap-2">
              <Label className="font-semibold text-gray-700 dark:text-gray-300">
                Blok / No Rumah <span className="text-red-500">*</span>
              </Label>
              <Input
                type="text"
                name="blok_no"
                value={formData.blok_no}
                onChange={handleInputChange}
                placeholder="e.g. A-1, B-5, GG-11"
                className="h-9 dark:bg-gray-800 dark:border-gray-700"
              />
            </div>

            <div className="flex flex-col gap-2">
              <Label className="font-semibold text-gray-700 dark:text-gray-300">
                Nama Jalan
              </Label>
              <Input
                type="text"
                name="nama_jalan"
                value={formData.nama_jalan}
                onChange={handleInputChange}
                placeholder="e.g. Jl. Merdeka"
                className="h-9 dark:bg-gray-800 dark:border-gray-700"
              />
            </div>
          </div>

          {/* Row 2: Pemilik Sah & Kategori */}
          <div className="grid grid-cols-2 gap-4">
            <div className="flex flex-col gap-2">
              <Label className="font-semibold text-gray-700 dark:text-gray-300">
                Pemilik Sah
              </Label>
              <Input
                type="text"
                name="pemilik_sah"
                value={formData.pemilik_sah}
                onChange={handleInputChange}
                placeholder="Nama pemilik sah"
                className="h-9 dark:bg-gray-800 dark:border-gray-700"
              />
            </div>
          </div>

          {/* Row 3: Jenis Pemilik & Status Penghuni */}
          <div className="grid grid-cols-2 gap-4">
            <div className="flex flex-col gap-2">
              <Label className="font-semibold text-gray-700 dark:text-gray-300">
                Jenis Pemilik <span className="text-red-500">*</span>
              </Label>
              <Select value={formData.jenis_pemilik} onValueChange={handleJenisPemilikChange}>
                <SelectTrigger className="h-9 dark:bg-gray-800 dark:border-gray-700">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Milik Sendiri">Milik Sendiri</SelectItem>
                  <SelectItem value="Sewa / Kontrak">Sewa / Kontrak</SelectItem>
                  <SelectItem value="Lainnya">Lainnya</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="flex flex-col gap-2">
              <Label className="font-semibold text-gray-700 dark:text-gray-300">
                Status Penghuni <span className="text-red-500">*</span>
              </Label>
              <Select value={formData.status_penghuni} onValueChange={handleStatusPenguniChange}>
                <SelectTrigger className="h-9 dark:bg-gray-800 dark:border-gray-700">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="Pemilik">Pemilik</SelectItem>
                  <SelectItem value="Penghuni Kontrak">Penghuni Kontrak</SelectItem>
                  <SelectItem value="Keluarga Pemilik">Keluarga Pemilik</SelectItem>
                  <SelectItem value="Pemilik Tidak Tinggal">Pemilik Tidak Tinggal</SelectItem>
                  <SelectItem value="Rumah Usaha">Rumah Usaha</SelectItem>
                  <SelectItem value="Kosong">Kosong</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Row 5: Checkboxes */}
          <div className="flex gap-4">
            <div className="flex items-center gap-2">
              <Checkbox
                id="sedang_kosong"
                checked={formData.sedang_kosong}
                onCheckedChange={() => handleCheckboxChange('sedang_kosong')}
              />
              <Label htmlFor="sedang_kosong" className="font-normal cursor-pointer">
                Sedang Kosong
              </Label>
            </div>

            <div className="flex items-center gap-2">
              <Checkbox
                id="aktif"
                checked={formData.aktif}
                onCheckedChange={() => handleCheckboxChange('aktif')}
              />
              <Label htmlFor="aktif" className="font-normal cursor-pointer">
                Aktif
              </Label>
            </div>
          </div>

          {/* Remark */}
          <div className="flex flex-col gap-2">
            <Label htmlFor="remark" className="font-semibold text-gray-700 dark:text-gray-300">
              Catatan (Remark)
            </Label>
            <textarea
              id="remark"
              name="remark"
              placeholder="Catatan: Opsional"
              value={formData.remark}
              onChange={handleInputChange}
              className="h-20 p-3 border border-gray-300 dark:border-gray-600 rounded-md bg-white dark:bg-gray-800 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-cyan-500"
            />
          </div>

          {/* Buttons */}
          <div className="flex gap-3 justify-end pt-4 border-t dark:border-gray-700">
            <Button
              type="button"
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700"
            >
              Batal
            </Button>
            <Button
              type="submit"
              disabled={submitting}
              className="bg-cyan-500 hover:bg-cyan-600 text-white"
            >
              {submitting ? 'Menyimpan...' : rumah ? 'Update' : 'Simpan'}
            </Button>
          </div>
        </form>
      </DialogContent>
    </Dialog>
  );
}
