import { useState } from "react";
import { Button } from "@/components/ui/button";
import { API_BASE_URL } from "@/config/api";
import {
  Table, TableBody, TableCell, TableHead, TableHeader, TableRow
} from "@/components/ui/table";
import {
  AlertDialog,
  AlertDialogHeader,
  AlertDialogFooter,
  AlertDialogTitle,
  AlertDialogContent,
  AlertDialogCancel,
  AlertDialogAction
} from "@/components/ui/alert-dialog";
import { CheckCircle2, XCircle, ChevronDown, ChevronRight } from "lucide-react";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";
import { useRolePermissions } from "@/hooks/useRolePermissions";

export default function KaryawanTable({
  data,
  onEdit,
  onDelete,
  selectedRows,
  setSelectedRows
}) {
  const [sortField, setSortField] = useState("");
  const [sortDir, setSortDir] = useState("asc");
  const { token, user } = useAuth(); // 🔐 JWT
  const { canRead, canUpdate: canEdit, canDelete } = useRolePermissions(user?.role, token);
  const [deleteConfirm, setDeleteConfirm] = useState(null);
  const [expandedRows, setExpandedRows] = useState([]);

  const toggleSort = (field) => {
    const newDir =
      sortField === field && sortDir === "asc" ? "desc" : "asc";
    setSortField(field);
    setSortDir(newDir);
  };

  const sortedData = [...data].sort((a, b) => {
    if (!sortField) return 0;
    const aVal = a[sortField] ?? "";
    const bVal = b[sortField] ?? "";
    return sortDir === "asc"
      ? aVal.toString().localeCompare(bVal.toString())
      : bVal.toString().localeCompare(aVal.toString());
  });

  const toggleRow = (id) => {
    setSelectedRows(
      selectedRows.includes(id)
        ? selectedRows.filter((r) => r !== id)
        : [...selectedRows, id]
    );
  };

  const toggleAll = () => {
    if (selectedRows.length === data.length) setSelectedRows([]);
    else setSelectedRows(data.map((k) => k.id));
  };

  const remove = async (id) => {
    try {
      const res = await fetch(`${API_BASE_URL}/api/karyawan/${id}`, {
        method: "DELETE",
        headers: {
          Authorization: `Bearer ${token}`,
        },
      });

      if (!res.ok) throw new Error();

      toast.success("Karyawan dihapus");
      onDelete();
    } catch {
      toast.error("Gagal menghapus karyawan");
    }
    setDeleteConfirm(null);
  };

  const formatDate = (val) => {
    if (!val) return "-";
    return new Date(val).toLocaleDateString("id-ID");
  };

  const toggleExpanded = (id) => {
    setExpandedRows(
      expandedRows.includes(id)
        ? expandedRows.filter((r) => r !== id)
        : [...expandedRows, id]
    );
  };

  return (
    <>
      <Table className="border rounded-lg bg-white dark:bg-gray-900 shadow-sm">
        <TableHeader>
          <TableRow className="dark:border-gray-700">
            {/* EXPAND ICON */}
            <TableHead className="w-10"></TableHead>

            {/* CHECKBOX */}
            <TableHead className="w-10">
              <input
                type="checkbox"
                checked={
                  data.length > 0 && selectedRows.length === data.length
                }
                onChange={toggleAll}
              />
            </TableHead>

            <TableHead
              onClick={() => toggleSort("nama_lengkap")}
              className="cursor-pointer dark:text-gray-300"
            >
              Nama {sortField === "nama_lengkap" && (sortDir === "asc" ? "▲" : "▼")}
            </TableHead>

            <TableHead className="dark:text-gray-300">Email</TableHead>
            <TableHead className="dark:text-gray-300">Nomor WhatsApp</TableHead>
            <TableHead className="dark:text-gray-300">Jabatan</TableHead>
            <TableHead className="dark:text-gray-300">Status Aktif</TableHead>
            {/* <TableHead className="dark:text-gray-300">Awal Bekerja</TableHead>
            <TableHead className="dark:text-gray-300">Nama Bank</TableHead>
            <TableHead className="dark:text-gray-300">Nama Rekening</TableHead>
            <TableHead className="dark:text-gray-300">Nomor Rekening</TableHead> */}
            <TableHead className="text-center dark:text-gray-300">Sudah Punya User?</TableHead>
            {canRead('karyawan') && canEdit('karyawan') && (<TableHead className="text-right dark:text-gray-300">Edit</TableHead>)}
          </TableRow>
        </TableHeader>

        <TableBody>
          {sortedData.map((k) => (
            <>
              <TableRow key={k.id} className="dark:border-gray-700 dark:hover:bg-gray-800">
                {/* EXPAND ICON */}
                <TableCell 
                  className="w-10 cursor-pointer"
                  onClick={() => toggleExpanded(k.id)}
                >
                  {expandedRows.includes(k.id) ? (
                    <ChevronDown className="w-5 h-5 text-gray-600 dark:text-gray-400" />
                  ) : (
                    <ChevronRight className="w-5 h-5 text-gray-600 dark:text-gray-400" />
                  )}
                </TableCell>

                {/* CHECKBOX */}
                <TableCell className="w-10">
                  <input
                    type="checkbox"
                    checked={selectedRows.includes(k.id)}
                    onChange={() => toggleRow(k.id)}
                  />
                </TableCell>

                <TableCell className="dark:text-gray-200">{k.nama_lengkap}</TableCell>
                <TableCell className="dark:text-gray-200">{k.email || "-"}</TableCell>
                <TableCell className="dark:text-gray-200">{k.whatsapp || "-"}</TableCell>
                <TableCell className="dark:text-gray-200">{k.jabatan || "-"}</TableCell>

                <TableCell className="dark:text-gray-200">
                  <span
                    className={`px-2 py-1 rounded-full text-xs font-semibold ${
                      k.status === "active"
                        ? "bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-200"
                        : "bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200"
                    }`}
                  >
                    {k.status === "active" ? "✓ Aktif" : "✗ Tidak Aktif"}
                  </span>
                </TableCell>

                {/* <TableCell className="dark:text-gray-200">{formatDate(k.awal_bekerja)}</TableCell>
                <TableCell className="dark:text-gray-200">{k.nama_bank || "-"}</TableCell>
                <TableCell className="dark:text-gray-200">{k.nama_rekening || "-"}</TableCell>
                <TableCell className="dark:text-gray-200">{k.nomor_rekening || "-"}</TableCell> */}

                <TableCell className="text-center">
                  {k.has_user ? (
                    <span className="inline-flex items-center gap-2 px-3 py-1 rounded-full
                    bg-green-100 text-green-700 dark:bg-green-900 dark:text-green-200 text-xs font-semibold">
                      <CheckCircle2 className="w-4 h-4" />
                      SUDAH PUNYA USER
                    </span>
                  ) : (
                    <span className="inline-flex items-center gap-2 px-3 py-1 rounded-full
                    bg-red-100 text-red-700 dark:bg-red-900 dark:text-red-200 text-xs font-semibold">
                      <XCircle className="w-4 h-4" />
                      BELUM PUNYA USER
                    </span>
                  )}
                </TableCell>

                <TableCell className="text-right">
                  {canRead('karyawan') && canEdit('karyawan') && (
                    <Button
                      size="sm"
                      onClick={() => onEdit(k)}
                      className="bg-blue-500 hover:bg-blue-600 text-white"
                    >
                      Edit
                    </Button>
                  )}
                </TableCell>
              </TableRow>

              {/* EXPANDED DETAIL ROW */}
              {expandedRows.includes(k.id) && (
                <TableRow className="dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                  <TableCell colSpan="12" className="p-6">
                    <div className="grid grid-cols-2 md:grid-cols-3 gap-6">
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Nama Lengkap</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{k.nama_lengkap}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Email</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{k.email || "-"}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">No WhatsApp</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">
                          {k.country_code}{k.whatsapp || "-"}
                        </p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Jabatan</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{k.jabatan || "-"}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Status</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">
                          {k.status === "active" ? "Aktif" : "Tidak Aktif"}
                        </p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Awal Bekerja</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{formatDate(k.awal_bekerja)}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Nama Bank</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{k.nama_bank || "-"}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Nama Rekening</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{k.nama_rekening || "-"}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Nomor Rekening</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{k.nomor_rekening || "-"}</p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Sudah Punya User?</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">
                          {k.has_user ? "✓ Ya" : "✗ Belum"}
                        </p>
                      </div>
                      <div>
                        <p className="text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase">Tanggal Dibuat</p>
                        <p className="text-sm font-medium text-gray-900 dark:text-gray-100 mt-1">{formatDate(k.created_at)}</p>
                      </div>
                      <div className="flex gap-2 items-end">
                        {canDelete(user?.role) && (
                          <Button
                            size="sm"
                            variant="destructive"
                            onClick={() => setDeleteConfirm(k.id)}
                          >
                            Hapus
                          </Button>
                        )}
                      </div>
                    </div>
                  </TableCell>
                </TableRow>
              )}
            </>
          ))}
        </TableBody>
      </Table>

      {/* DELETE CONFIRMATION */}
      <AlertDialog open={deleteConfirm !== null} onOpenChange={(open) => !open && setDeleteConfirm(null)}>
        <AlertDialogContent className="dark:bg-gray-900 dark:text-gray-100">
          <AlertDialogHeader>
            <AlertDialogTitle>Hapus Karyawan?</AlertDialogTitle>
          </AlertDialogHeader>
          <p className="text-sm text-gray-600 dark:text-gray-400">
            Tindakan ini tidak dapat dibatalkan.
          </p>
          <AlertDialogFooter>
            <AlertDialogCancel className="dark:bg-gray-800 dark:text-gray-200">
              Batal
            </AlertDialogCancel>
            <AlertDialogAction
              onClick={() => remove(deleteConfirm)}
              className="bg-red-600 hover:bg-red-700"
            >
              Hapus
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </>
  );
}
