import React, { useRef, useState, useEffect, useCallback } from 'react';
import { Camera, RotateCcw, Loader2, AlertTriangle } from 'lucide-react';
import { Button } from '@/components/ui/button';

/**
 * Ambil foto selfie dari webcam device. Tidak menyimpan apa pun sendiri —
 * begitu foto diambil & dikonfirmasi, blob-nya dikirim ke parent lewat
 * onCapture(blob, previewUrl).
 */
export default function CameraCapture({ onCapture }) {
  const videoRef = useRef(null);
  const canvasRef = useRef(null);
  const streamRef = useRef(null);
  const [starting, setStarting] = useState(true);
  const [error, setError] = useState(null);
  const [preview, setPreview] = useState(null); // { blob, url }

  const startCamera = useCallback(async () => {
    setError(null);
    setStarting(true);
    try {
      const stream = await navigator.mediaDevices.getUserMedia({
        video: { facingMode: 'user', width: { ideal: 720 }, height: { ideal: 720 } },
        audio: false,
      });
      streamRef.current = stream;
      if (videoRef.current) {
        videoRef.current.srcObject = stream;
        await videoRef.current.play();
      }
    } catch (err) {
      setError(
        err?.name === 'NotAllowedError'
          ? 'Akses kamera ditolak. Izinkan akses kamera di browser untuk absen.'
          : 'Tidak bisa mengakses kamera perangkat ini.'
      );
    } finally {
      setStarting(false);
    }
  }, []);

  const stopCamera = useCallback(() => {
    streamRef.current?.getTracks()?.forEach(t => t.stop());
    streamRef.current = null;
  }, []);

  useEffect(() => {
    startCamera();
    return () => stopCamera();
  }, []);

  const handleTakePhoto = () => {
    const video = videoRef.current;
    const canvas = canvasRef.current;
    if (!video || !canvas) return;
    const size = Math.min(video.videoWidth, video.videoHeight);
    canvas.width = size;
    canvas.height = size;
    const ctx = canvas.getContext('2d');
    // Crop tengah jadi persegi + mirror horizontal (selfie natural)
    const sx = (video.videoWidth - size) / 2;
    const sy = (video.videoHeight - size) / 2;
    ctx.translate(size, 0);
    ctx.scale(-1, 1);
    ctx.drawImage(video, sx, sy, size, size, 0, 0, size, size);
    canvas.toBlob(blob => {
      const url = URL.createObjectURL(blob);
      setPreview({ blob, url });
      stopCamera();
    }, 'image/jpeg', 0.85);
  };

  const handleRetake = () => {
    if (preview?.url) URL.revokeObjectURL(preview.url);
    setPreview(null);
    startCamera();
  };

  useEffect(() => {
    if (preview) onCapture(preview.blob, preview.url);
  }, [preview]);

  return (
    <div className="flex flex-col items-center gap-3">
      <div className="relative w-64 h-64 rounded-full overflow-hidden bg-gray-900 flex items-center justify-center border-4 border-primary/20">
        {error ? (
          <div className="text-center text-white p-4 text-xs flex flex-col items-center gap-2">
            <AlertTriangle size={24} className="text-amber-400" />
            {error}
          </div>
        ) : preview ? (
          <img src={preview.url} alt="Preview selfie" className="w-full h-full object-cover" />
        ) : (
          <>
            {starting && <Loader2 className="absolute animate-spin text-white" size={28} />}
            <video
              ref={videoRef}
              className="w-full h-full object-cover -scale-x-100"
              muted
              playsInline
            />
          </>
        )}
        <canvas ref={canvasRef} className="hidden" />
      </div>

      {error ? (
        <Button variant="outline" size="sm" onClick={startCamera} className="gap-1.5">
          <RotateCcw size={14} /> Coba Lagi
        </Button>
      ) : preview ? (
        <Button variant="outline" size="sm" onClick={handleRetake} className="gap-1.5">
          <RotateCcw size={14} /> Ambil Ulang
        </Button>
      ) : (
        <Button size="sm" onClick={handleTakePhoto} disabled={starting} className="gap-1.5">
          <Camera size={14} /> Ambil Foto
        </Button>
      )}
    </div>
  );
}
