import React from 'react';

/**
 * Peta sederhana pakai embed OpenStreetMap — tidak butuh API key atau
 * package tambahan. `extraMarker` opsional untuk menampilkan 2 titik
 * sekaligus (mis. lokasi kantor vs lokasi absen).
 */
export default function LocationMap({ lat, lng, height = 220, zoomBox = 0.004 }) {
  if (lat == null || lng == null) {
    return (
      <div
        className="flex items-center justify-center rounded-lg bg-gray-100 text-gray-400 text-sm"
        style={{ height }}
      >
        Lokasi tidak tersedia
      </div>
    );
  }
  const bbox = `${lng - zoomBox},${lat - zoomBox},${lng + zoomBox},${lat + zoomBox}`;
  const src = `https://www.openstreetmap.org/export/embed.html?bbox=${bbox}&layer=mapnik&marker=${lat},${lng}`;
  const externalUrl = `https://www.openstreetmap.org/?mlat=${lat}&mlon=${lng}#map=17/${lat}/${lng}`;

  return (
    <div className="rounded-lg overflow-hidden border" style={{ height }}>
      <iframe
        title={`Lokasi ${lat},${lng}`}
        src={src}
        style={{ width: '100%', height: '100%', border: 0 }}
        loading="lazy"
      />
      <a
        href={externalUrl}
        target="_blank"
        rel="noreferrer"
        className="block text-center text-xs text-primary py-1 bg-gray-50 hover:underline"
      >
        Buka di peta lebih besar ↗
      </a>
    </div>
  );
}
