import React, { useMemo } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from './ui/select';

const defaultFormatter = (num) => new Intl.NumberFormat('id-ID', {
  style: 'currency',
  currency: 'IDR',
  minimumFractionDigits: 0
}).format(num || 0);

const LineChart = ({
  title,
  data,
  dropdownOptions = [],
  defaultValue,
  selectedValue,
  onDropdownChange,
  value,
  showValue = true,
  valueFormatter = defaultFormatter
}) => {
  // Find min and max values for scaling
  const values = data.map(d => d.value);
  const maxValue = Math.max(...values, 1);
  const minValue = Math.min(...values, 0);
  const periodLabel = data.length ? `${data[0].label} - ${data[data.length - 1].label}` : '-';
  const highlightedPoint = data[data.length - 1];
  const formattedValue = showValue ? (typeof value === 'string' ? value : valueFormatter(value)) : null;
  const summaryItems = useMemo(() => data.map((item, index) => ({
    key: `${item.label}-${index}`,
    label: item.label,
    value: valueFormatter(item.value)
  })), [data, valueFormatter]);
  const hasDropdown = dropdownOptions.length > 0;
  const resolvedSelectValue = selectedValue ?? defaultValue ?? dropdownOptions[0]?.value ?? '';
  const handleDropdownChange = onDropdownChange || (() => {});
  
  // SVG dimensions
  const width = 600;
  const height = 120;
  const padding = { top: 10, right: 10, bottom: 20, left: 10 };
  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;
  
  // Calculate points for the line
  const points = data.map((item, index) => {
    const x = padding.left + (index / (data.length - 1)) * chartWidth;
    const y = padding.top + chartHeight - ((item.value - minValue) / (maxValue - minValue || 1)) * chartHeight;
    return { x, y, value: item.value };
  });
  
  // Create path for line
  const linePath = points
    .map((point, index) => `${index === 0 ? 'M' : 'L'} ${point.x},${point.y}`)
    .join(' ');
  
  // Create path for area fill
  const areaPath = `${linePath} L ${points[points.length - 1].x},${height - padding.bottom} L ${padding.left},${height - padding.bottom} Z`;

  return (
    <Card className="hover:shadow-lg transition-shadow duration-200">
      <CardHeader>
        <div className="flex flex-col gap-1">
          <div className="flex items-center justify-between gap-4">
            <div>
              <CardTitle className="text-sm font-medium text-gray-600 dark:text-gray-400">
                {title}
              </CardTitle>
              <p className="text-xs text-gray-500">
                Periode: {periodLabel}
              </p>
            </div>
            {hasDropdown && (
              <Select
                value={resolvedSelectValue}
                onValueChange={handleDropdownChange}
              >
                <SelectTrigger className="w-32 h-8 text-xs">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  {dropdownOptions.map((option) => (
                    <SelectItem key={option.value} value={option.value}>
                      {option.label}
                    </SelectItem>
                  ))}
                </SelectContent>
              </Select>
            )}
          </div>
          {highlightedPoint && (
            <div className="text-xs text-teal-600 dark:text-teal-300 font-medium">
              Tren terakhir: {highlightedPoint.label} · {valueFormatter(highlightedPoint.value)}
            </div>
          )}
        </div>
      </CardHeader>
      <CardContent>
        <div className="space-y-2">
          {showValue && (
            <div className="text-4xl font-bold text-gray-900 dark:text-white">
              {formattedValue}
            </div>
          )}
          <svg width="100%" height={height} viewBox={`0 0 ${width} ${height}`} className="overflow-visible">
            {/* Area fill */}
            <path
              d={areaPath}
              fill="url(#gradient)"
              opacity="0.2"
            />
            
            {/* Line */}
            <path
              d={linePath}
              stroke="#06b6d4"
              strokeWidth="2.5"
              fill="none"
              strokeLinecap="round"
              strokeLinejoin="round"
            />
            
            {/* Points */}
            {points.map((point, index) => (
              <circle
                key={index}
                cx={point.x}
                cy={point.y}
                r="4"
                fill="#06b6d4"
                className="transition-all duration-200 hover:r-6"
              />
            ))}
            
            {/* Gradient definition */}
            <defs>
              <linearGradient id="gradient" x1="0%" y1="0%" x2="0%" y2="100%">
                <stop offset="0%" stopColor="#06b6d4" stopOpacity="0.8" />
                <stop offset="100%" stopColor="#06b6d4" stopOpacity="0.1" />
              </linearGradient>
            </defs>
          </svg>
          <div className="pt-4 border-t border-gray-100 dark:border-gray-700">
            <div className="text-xs font-semibold text-gray-500 uppercase tracking-wide mb-2">
              Rincian Bulanan
            </div>
            <div className="overflow-x-auto">
              <div className="flex gap-5 min-w-max">
                {summaryItems.map((item) => (
                  <div key={item.key} className="flex flex-col text-sm">
                    <span className="text-xs text-gray-500">{item.label}</span>
                    <span className="font-semibold text-gray-900 dark:text-white">{item.value}</span>
                  </div>
                ))}
              </div>
            </div>
          </div>
        </div>
      </CardContent>
    </Card>
  );
};

export default LineChart;