import React, { useEffect, useState } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Button } from '@/components/ui/button';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Select, SelectTrigger, SelectValue, SelectContent, SelectItem } from '@/components/ui/select';
import { useAuth } from '@/contexts/AuthContext';
import { API_ENDPOINTS } from '@/config/api';
import { toast } from 'sonner';

export default function ThrBudgetForm({ open, onClose, editData, onSuccess, year }) {
    const { token } = useAuth();
    const [categories, setCategories] = useState([]);
    const [formData, setFormData] = useState({
        finance_category_id: '',
        total_thr: ''
    });
    const [loading, setLoading] = useState(false);

    useEffect(() => {
        if (open) {
            loadCategories();
            if (editData) {
                setFormData({
                    finance_category_id: editData.finance_category_id,
                    total_thr: editData.total_thr
                });
            } else {
                setFormData({ finance_category_id: '', total_thr: '' });
            }
        }
    }, [open, editData]);

    const loadCategories = async () => {
        try {
            const res = await fetch(API_ENDPOINTS.FINANCE_CATEGORY, {
                headers: { Authorization: `Bearer ${token}` }
            });
            if (res.ok) {
                const data = await res.json();
                // Filter only THR type categories
                setCategories(data.filter(c => c.tipe === 'THR'));
            }
        } catch (err) {
            console.error(err);
        }
    };

    const handleSubmit = async (e) => {
        e.preventDefault();
        setLoading(true);

        try {
            const payload = {
                finance_category_id: formData.finance_category_id,
                total_thr: parseFloat(formData.total_thr),
                year: parseInt(year)
            };

            const res = await fetch(API_ENDPOINTS.BUDGET_THR, {
                method: 'POST',
                headers: {
                    'Content-Type': 'application/json',
                    Authorization: `Bearer ${token}`
                },
                body: JSON.stringify(payload)
            });

            if (!res.ok) {
                const errData = await res.json().catch(() => ({}));
                throw new Error(errData.detail || 'Gagal menyimpan THR Budget');
            }

            toast.success(`Budget THR berhasil disimpan`);
            onSuccess();
            onClose();

        } catch (error) {
            toast.error(error.message);
        } finally {
            setLoading(false);
        }
    };

    return (
        <Dialog open={open} onOpenChange={onClose}>
            <DialogContent className="sm:max-w-md">
                <DialogHeader>
                    <DialogTitle>{editData ? 'Edit Budget THR' : 'Set Budget THR'}</DialogTitle>
                </DialogHeader>

                <form onSubmit={handleSubmit} className="space-y-4 py-4">
                    <div className="space-y-2">
                        <Label>Pos Keuangan</Label>
                        <Select
                            value={formData.finance_category_id}
                            onValueChange={(val) => setFormData({ ...formData, finance_category_id: val })}
                            disabled={!!editData}
                        >
                            <SelectTrigger>
                                <SelectValue placeholder="Pilih Pos THR..." />
                            </SelectTrigger>
                            <SelectContent>
                                {categories.map(cat => (
                                    <SelectItem key={cat.id} value={cat.id}>{cat.nama}</SelectItem>
                                ))}
                            </SelectContent>
                        </Select>
                    </div>

                    <div className="space-y-2">
                        <Label>Total THR (Setahun)</Label>
                        <div className="relative">
                            <span className="absolute left-3 top-2.5 text-gray-500 text-sm">Rp</span>
                            <Input
                                type="text"
                                placeholder="0"
                                className="pl-9"
                                value={formData.total_thr ? parseFloat(formData.total_thr.toString().replace(/\./g, '')).toLocaleString('id-ID') : ''}
                                onChange={(e) => {
                                    const value = e.target.value.replace(/\D/g, '');
                                    setFormData({ ...formData, total_thr: value });
                                }}
                                required
                            />
                        </div>
                        <p className="text-xs text-gray-500">Target simpanan per bulan: <strong>Rp {formData.total_thr ? (parseFloat(formData.total_thr) / 12).toLocaleString('id-ID', { maximumFractionDigits: 0 }) : 0}</strong></p>
                    </div>

                    <DialogFooter>
                        <Button type="button" variant="outline" onClick={onClose}>Batal</Button>
                        <Button type="submit" disabled={loading} className="bg-blue-600">
                            {loading ? 'Menyimpan...' : 'Simpan'}
                        </Button>
                    </DialogFooter>
                </form>
            </DialogContent>
        </Dialog>
    );
}
