import React, { useState, useEffect } from 'react';
import { Dialog, DialogContent, DialogHeader, DialogTitle, DialogFooter } from '@/components/ui/dialog';
import { Label } from '@/components/ui/label';
import { Input } from '@/components/ui/input';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/components/ui/select';
import { Button } from '@/components/ui/button';
import { API_ENDPOINTS } from '@/config/api';
import { useAuth } from '@/contexts/AuthContext';

export default function FundAllocationForm({ open = false, onClose = () => { } }) {
  const { token } = useAuth();
  const [funds, setFunds] = useState([]);
  const [fundId, setFundId] = useState('');
  const [month, setMonth] = useState(new Date().getMonth() + 1);
  const [year, setYear] = useState(new Date().getFullYear());
  const [createKeuangan, setCreateKeuangan] = useState(false);

  useEffect(() => {
    const loadFunds = async () => {
      try {
        const res = await fetch(API_ENDPOINTS.DANA_FUNDS, { headers: { Authorization: `Bearer ${token}` } });
        if (res.ok) setFunds(await res.json());
      } catch (err) { console.error(err); }
    };
    if (token) loadFunds();
  }, [token]);

  const handleSubmit = async () => {
    try {
      const res = await fetch(API_ENDPOINTS.DANA_ALLOCATIONS, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json', Authorization: `Bearer ${token}` },
        body: JSON.stringify({ fund_id: fundId, amount: 0, allocation_month: Number(month), allocation_year: Number(year), create_keuangan: createKeuangan })
      });
      if (res.ok) {
        onClose();
      } else {
        console.error(await res.json());
      }
    } catch (err) { console.error(err); }
  };

  return (
    <Dialog open={open} onOpenChange={onClose}>
      <DialogContent className="max-w-md">
        <DialogHeader>
          <DialogTitle>Tambah Alokasi Bulanan</DialogTitle>
        </DialogHeader>
        <div className="space-y-3">
          <div>
            <Label>Pilih Dana</Label>
            <Select value={fundId} onValueChange={(v) => setFundId(v)}>
              <SelectTrigger><SelectValue placeholder="-- Pilih --" /></SelectTrigger>
              <SelectContent>
                {funds.map(f => (
                  <SelectItem key={f.id} value={f.id}>{f.fund_name}</SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>


          <div className="bg-blue-50 border border-blue-200 rounded p-3">
            <p className="text-sm text-blue-800">
              <strong>Catatan:</strong> Nominal alokasi akan dihitung otomatis berdasarkan:
              <br />
              (Nominal Bulanan Dana / Total Rumah) × Jumlah IPL Lunas
            </p>
          </div>

          <div className="flex items-center gap-2">
            <input id="createKeu" type="checkbox" checked={createKeuangan} onChange={(e) => setCreateKeuangan(e.target.checked)} />
            <label htmlFor="createKeu" className="text-sm text-gray-600">Rekam ke Keuangan (opsional)</label>
          </div>

          <div className="flex gap-2">
            <div>
              <Label>Bulan</Label>
              <Select value={String(month)} onValueChange={(v) => setMonth(Number(v))}>
                <SelectTrigger><SelectValue /></SelectTrigger>
                <SelectContent>
                  {Array.from({ length: 12 }, (_, i) => i + 1).map(m => (
                    <SelectItem key={m} value={String(m)}>{new Date(2024, m - 1).toLocaleString('id-ID', { month: 'long' })}</SelectItem>
                  ))}
                </SelectContent>
              </Select>
            </div>
            <div>
              <Label>Tahun</Label>
              <Input type="number" value={year} onChange={(e) => setYear(e.target.value)} />
            </div>
          </div>
        </div>
        <DialogFooter>
          <Button variant="outline" onClick={onClose}>Batal</Button>
          <Button onClick={handleSubmit} className="bg-amber-600">Simpan</Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}
