import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from './ui/card';
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue
} from './ui/select';

const COLORS = {
  pemasukan: '#10b981',
  pengeluaran: '#ef4444'
};

const LineComparisonChart = ({
  title,
  data,
  dropdownOptions,
  defaultValue,
  selectedValue,
  onValueChange,
  frameless = false,
  className = ''
}) => {
  const months = data.length;
  const values = data.flatMap((item) => [item.pemasukan, item.pengeluaran]);
  const maxValue = Math.max(...values, 1);

  const width = 720;
  const height = 300;
  const padding = { top: 40, right: 30, bottom: 50, left: 80 };
  const chartWidth = width - padding.left - padding.right;
  const chartHeight = height - padding.top - padding.bottom;
  const pointSpacing = chartWidth / Math.max(months - 1, 1);

  const formatCurrency = (value) =>
    new Intl.NumberFormat('id-ID', {
      style: 'currency',
      currency: 'IDR',
      minimumFractionDigits: 0
    }).format(value);

  const buildPath = (key) => {
    return data
      .map((item, index) => {
        const x = padding.left + index * pointSpacing;
        const scaled = (item[key] / maxValue) * chartHeight;
        const y = height - padding.bottom - scaled;
        return `${index === 0 ? 'M' : 'L'} ${x},${y}`;
      })
      .join(' ');
  };

  const renderPoints = (key) => {
    return data.map((item, index) => {
      const x = padding.left + index * pointSpacing;
      const scaled = (item[key] / maxValue) * chartHeight;
      const y = height - padding.bottom - scaled;
      return (
        <circle
          key={`${key}-${index}`}
          cx={x}
          cy={y}
          r="4"
          fill={COLORS[key]}
        >
          <title>{`${item.month} ${formatCurrency(item[key])}`}</title>
        </circle>
      );
    });
  };

  const totalPemasukan = data.length > 0 ? data[data.length - 1].pemasukan : 0;
  const totalPengeluaran = data.reduce((sum, item) => sum + item.pengeluaran, 0);

  const yTicks = 5;
  const yTickValues = Array.from({ length: yTicks }, (_, idx) => (idx / (yTicks - 1)) * maxValue);

  const chartContent = (
    <>
      <div className="mb-6 grid grid-cols-2 gap-4">
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 rounded-full" style={{ backgroundColor: COLORS.pemasukan }}></div>
          <div>
            <p className="text-xs text-gray-500 dark:text-gray-400">Total Pemasukan</p>
            <p className="text-base font-semibold text-gray-900 dark:text-white">
              {formatCurrency(totalPemasukan)}
            </p>
          </div>
        </div>
        <div className="flex items-center gap-2">
          <div className="w-4 h-4 rounded-full" style={{ backgroundColor: COLORS.pengeluaran }}></div>
          <div>
            <p className="text-xs text-gray-500 dark:text-gray-400">Total Pengeluaran</p>
            <p className="text-base font-semibold text-gray-900 dark:text-white">
              {formatCurrency(totalPengeluaran)}
            </p>
          </div>
        </div>
      </div>

      <svg width="100%" height={height} viewBox={`0 0 ${width} ${height}`} className="overflow-visible">
        {yTickValues.map((value, idx) => {
          const y = height - padding.bottom - (value / maxValue) * chartHeight;
          return (
            <g key={`grid-${idx}`}>
              <line
                x1={padding.left}
                y1={y}
                x2={width - padding.right}
                y2={y}
                stroke="#e5e7eb"
                strokeWidth="1"
                className="dark:stroke-gray-700"
              />
              <text
                x={padding.left - 10}
                y={y + 4}
                textAnchor="end"
                fontSize="11"
                fill="#6b7280"
                className="dark:fill-gray-500"
              >
                {formatCurrency(value)}
              </text>
            </g>
          );
        })}

        {data.map((item, index) => {
          const x = padding.left + index * pointSpacing;
          return (
            <text
              key={`label-${index}`}
              x={x}
              y={height - padding.bottom + 20}
              textAnchor="middle"
              fontSize="12"
              fill="#6b7280"
              className="dark:fill-gray-500"
            >
              {item.month}
            </text>
          );
        })}

        <path
          d={buildPath('pemasukan')}
          stroke={COLORS.pemasukan}
          strokeWidth="3"
          fill="none"
          strokeLinecap="round"
        />
        <path
          d={buildPath('pengeluaran')}
          stroke={COLORS.pengeluaran}
          strokeWidth="3"
          fill="none"
          strokeLinecap="round"
        />

        {renderPoints('pemasukan')}
        {renderPoints('pengeluaran')}
      </svg>
    </>
  );

  if (frameless) {
    return (
      <div className={`space-y-4 ${className}`}>
        {chartContent}
      </div>
    );
  }

  return (
    <Card className={`hover:shadow-lg transition-shadow duration-200 ${className}`}>
      <CardHeader>
        <div className="flex items-center justify-between">
          <CardTitle className="text-sm font-medium text-gray-600 dark:text-gray-400">
            {title}
          </CardTitle>
          {dropdownOptions?.length > 0 && (
            <Select
              value={selectedValue?.toString()}
              defaultValue={defaultValue?.toString()}
              onValueChange={(val) => onValueChange && onValueChange(Number(val))}
            >
              <SelectTrigger className="w-28 h-8 text-xs">
                <SelectValue />
              </SelectTrigger>
              <SelectContent>
                {dropdownOptions.map((option) => (
                  <SelectItem key={option.value} value={option.value.toString()}>
                    {option.label}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          )}
        </div>
      </CardHeader>
      <CardContent>
        {chartContent}
      </CardContent>
    </Card>
  );
};

export default LineComparisonChart;
