import React, { useState, useEffect } from 'react';
import { Stars, StarPicker } from './Stars';
import { ImageGalleryGrid } from './ImageGallery';
import { API_ENDPOINTS } from '@/config/api';
import { useToast } from './Toast';
import { useRolePermissions } from "@/hooks/useRolePermissions";
import { useAuth } from "@/contexts/AuthContext";
import { AlertDialog, AlertDialogContent, AlertDialogHeader, AlertDialogFooter, AlertDialogTitle, AlertDialogOverlay ,AlertDialogCancel, AlertDialogAction, AlertDialogPortal } from "@/components/ui/alert-dialog";


const SOC_CONFIG = [
  { key: 'instagram', icon: '📸', label: 'Instagram', base: 'https://instagram.com/' },
  { key: 'facebook',  icon: '👍', label: 'Facebook',  base: 'https://facebook.com/' },
  { key: 'tiktok',    icon: '🎵', label: 'TikTok',    base: 'https://tiktok.com/@' },
  { key: 'twitter',   icon: '🐦', label: 'Twitter',   base: 'https://twitter.com/' },
  { key: 'youtube',   icon: '▶️', label: 'YouTube',   base: 'https://youtube.com/' },
];

function getCatIcon(name, cats) {
  return cats.find(c => c.nama === name)?.icon || '📌';
}

export default function DetailModal({ item, categories, onClose, onEdit, onDelete }) {
  const [reviews, setReviews]       = useState([]);
  const [loadingRev, setLoadingRev] = useState(true);
  const [showForm, setShowForm]     = useState(false);
  const [revName, setRevName]       = useState('');
  const [revHouse, setRevHouse]     = useState('');
  const [revRating, setRevRating]   = useState(5);
  const [revComment, setRevComment] = useState('');
  const [submitting, setSubmitting] = useState(false);
  const [images, setImages] = useState(item.images || []);
  const { show } = useToast();
  const { token, logout, user } = useAuth(); // 🔥 AMBIL TOKEN & USER
  const { canCreate, canUpdate: canEdit, canDelete } = useRolePermissions(user?.role, token);
  // Selain izin role (canEdit/canDelete), listing hanya boleh diubah/dihapus
  // oleh admin ATAU oleh user yang menambahkannya sendiri. Listing lama
  // tanpa created_by_user_id (dibuat sebelum fitur ini ada) dianggap tidak
  // diketahui pemiliknya — hanya admin yang boleh mengubahnya.
  const isAdmin = user?.role === 'admin';
  const isOwner = !!item.created_by_user_id && item.created_by_user_id === user?.id;
  const canManageThisListing = isAdmin || isOwner;
  
  const [openDeleteImage, setOpenDeleteImage] = useState(false);
  const [selectedImgIndex, setSelectedImgIndex] = useState(null);
  const [openDeleteReview, setOpenDeleteReview] = useState(false);
  const [selectedReviewId, setSelectedReviewId] = useState(null);

  useEffect(() => {
    API_ENDPOINTS.getReviews(item.id)
      .then(setReviews)
      .finally(() => setLoadingRev(false));
  }, [item.id]);

  const handleSubmitReview = async () => {
    if (!revName.trim()) { show('Nama wajib diisi', 'error'); return; }
    if (!revRating)      { show('Pilih rating bintang', 'error'); return; }
    setSubmitting(true);
    try {
      await API_ENDPOINTS.addReview(item.id, {
        nama_reviewer: revName,
        no_rumah_reviewer: revHouse,
        rating: revRating,
        komentar: revComment,
      });
      show('Review ditambahkan! Terima kasih 🙏', 'success');
      const fresh = await API_ENDPOINTS.getReviews(item.id);
      setReviews(fresh);
      setRevName(''); setRevHouse(''); setRevRating(5); setRevComment('');
      setShowForm(false);
    } catch {
      show('Gagal mengirim review', 'error');
    }
    setSubmitting(false);
  };

  const handleDelReview = (rid) => {
  setSelectedReviewId(rid);
  setOpenDeleteReview(true);
 };

  const handleDelImage = (imgIndex) => {
  setSelectedImgIndex(imgIndex);
  setOpenDeleteImage(true);
 };

const confirmDeleteReview = async () => {
  if (!selectedReviewId) return;

  try {
    await API_ENDPOINTS.deleteReview(selectedReviewId);

    setReviews(r => r.filter(x => x.id !== selectedReviewId));
    show('Review dihapus', 'success');

    setOpenDeleteReview(false);
    setSelectedReviewId(null);
  } catch (e) {
    show(e.message || 'Gagal menghapus review', 'error');
  }
};

const confirmDeleteImage = async () => {
  if (selectedImgIndex === null) return;

  try {
    const res = await API_ENDPOINTS.deleteImage(item.id, selectedImgIndex);
    setImages(res.images || []);
    show('Foto dihapus', 'success');

    setOpenDeleteImage(false);
    setSelectedImgIndex(null);
  } catch (e) {
    show(e.message || 'Gagal menghapus foto', 'error');
  }
 };

  const icon     = getCatIcon(item.kategori, categories);
  const hasSocial = SOC_CONFIG.some(s => item[s.key]);
  const tags     = item.tags ? item.tags.split(',').map(t => t.trim()).filter(Boolean) : [];
  const avgRating = reviews.length
    ? reviews.reduce((a, r) => a + r.rating, 0) / reviews.length
    : 0;

  return (
    <div className="overlay" onClick={e => e.target === e.currentTarget && onClose()}>
      <div className="modal modal-lg">
        <div className="modal-header">
          <h2>Detail Listing</h2>
          <button className="btn-close" onClick={onClose}>×</button>
        </div>

        <div className="modal-body">
          {/* Hero */}
          <div className="detail-hero">
            <div className="detail-avatar">{icon}</div>
            <div className="detail-title-block">
              <h2>{item.nama}</h2>
              <div className="detail-badges">
                <span className="badge badge-cat">{icon} {item.kategori}</span>
                <span className={`badge ${item.aktif ? 'badge-active' : 'badge-inactive'}`}>
                  {item.aktif ? '✓ Aktif' : 'Nonaktif'}
                </span>
                {item.avg_rating > 0 && (
                  <Stars rating={item.avg_rating} count={item.total_reviews} />
                )}
              </div>
            </div>
          </div>

          {/* Foto Gallery */}
          {images.length > 0 && (
            <ImageGalleryGrid
              images={images}
              listingId={item.id}
              onDelete={handleDelImage}
              canDelete={canManageThisListing}
            />
          )}

          {/* Description */}
          {item.deskripsi && (
            <div className="detail-desc">{item.deskripsi}</div>
          )}

          {/* Info grid */}
          <div className="detail-grid">
            {item.nama_pemilik && (
              <div className="detail-item">
                <label>👤 Nama Pemilik</label>
                <span>{item.nama_pemilik}</span>
              </div>
            )}
            {item.no_rumah && (
              <div className="detail-item">
                <label>🏠 No. Rumah / Blok / Kantor</label>
                <span>{item.no_rumah}</span>
              </div>
            )}
            {item.alamat && (
              <div className="detail-item full">
                <label>📍 Alamat</label>
                <span>{item.alamat}</span>
              </div>
            )}
            {item.jam_operasional && (
              <div className="detail-item full">
                <label>🕒 Jam Operasional</label>
                <span>{item.jam_operasional}</span>
              </div>
            )}
            {item.telepon && (
              <div className="detail-item">
                <label>📞 Telepon</label>
                <a href={`tel:${item.telepon}`}>{item.telepon}</a>
              </div>
            )}
            {item.whatsapp && (
              <div className="detail-item">
                <label>💬 WhatsApp</label>
                <a href={`https://wa.me/${item.whatsapp}`} target="_blank" rel="noopener noreferrer">
                  {item.whatsapp}
                </a>
              </div>
            )}
            {item.email && (
              <div className="detail-item">
                <label>✉️ Email</label>
                <a href={`mailto:${item.email}`}>{item.email}</a>
              </div>
            )}
            {item.website && (
              <div className="detail-item">
                <label>🌐 Website</label>
                <a href={item.website} target="_blank" rel="noopener noreferrer">{item.website}</a>
              </div>
            )}
          </div>
          <AlertDialog open={openDeleteReview} onOpenChange={setOpenDeleteReview}>
            <AlertDialogPortal container={document.body}>
              
              <AlertDialogOverlay className="fixed inset-0 bg-black/60 z-[9998]" />
              
              <AlertDialogContent className="fixed z-[9999]">
                <AlertDialogHeader>
                  <AlertDialogTitle>
                    Hapus review ini?
                  </AlertDialogTitle>
                  <p className="text-sm text-gray-500">
                    Review akan dihapus permanen.
                  </p>
                </AlertDialogHeader>

                <AlertDialogFooter>
                  <AlertDialogCancel>Batal</AlertDialogCancel>

                  <AlertDialogAction
                    className="bg-red-600 hover:bg-red-700 text-white"
                    onClick={confirmDeleteReview}
                  >
                    Hapus
                  </AlertDialogAction>
                </AlertDialogFooter>
              </AlertDialogContent>

            </AlertDialogPortal>
          </AlertDialog>

          <AlertDialog open={openDeleteImage} onOpenChange={setOpenDeleteImage}>
            <AlertDialogPortal container={document.body}>
              
              <AlertDialogOverlay className="fixed inset-0 bg-black/60 z-[9998]" />
              
              <AlertDialogContent className="fixed z-[9999]">
                <AlertDialogHeader>
                  <AlertDialogTitle>
                    Hapus foto ini?
                  </AlertDialogTitle>
                  <p className="text-sm text-gray-500">
                    Foto akan dihapus permanen.
                  </p>
                </AlertDialogHeader>

                <AlertDialogFooter>
                  <AlertDialogCancel>Batal</AlertDialogCancel>

                  <AlertDialogAction
                    className="bg-red-600 hover:bg-red-700 text-white"
                    onClick={confirmDeleteImage}
                  >
                    Hapus
                  </AlertDialogAction>
                </AlertDialogFooter>
              </AlertDialogContent>

            </AlertDialogPortal>
          </AlertDialog>

          {/* Social media */}
          {hasSocial && (
            <div className="social-section">
              <h4>Media Sosial</h4>
              <div className="social-links">
                {SOC_CONFIG.filter(s => item[s.key]).map(s => (
                  <a
                    key={s.key}
                    href={`${s.base}${(item[s.key] || '').replace('@', '')}`}
                    target="_blank"
                    rel="noopener noreferrer"
                    className="soc-link"
                  >
                    <span>{s.icon}</span> {s.label}
                  </a>
                ))}
              </div>
            </div>
          )}

          {/* Tags */}
          {tags.length > 0 && (
            <div className="tags-row">
              {tags.map(t => <span key={t} className="tag">#{t}</span>)}
            </div>
          )}

          {/* Action buttons */}
          <div style={{ display: 'flex', gap: 8, flexWrap: 'wrap', marginBottom: 4 }}>
            {item.whatsapp && (
              <a
                href={`https://wa.me/${item.whatsapp}`}
                target="_blank"
                rel="noopener noreferrer"
                className="btn btn-wa"
              >
                💬 WhatsApp
              </a>
            )}
            {item.telepon && (
              <a href={`tel:${item.telepon}`} className="btn btn-tel">📞 Telepon</a>
            )}
            {canEdit('yellow-page') && canManageThisListing && (
            <button
              className="btn btn-secondary"
              style={{ marginLeft: 'auto' }}
              onClick={() => onEdit(item)}
            >
              ✏️ Edit
            </button>
            )}
            {canDelete('yellow-page') && canManageThisListing && (
            <button className="btn btn-danger" onClick={() => onDelete(item)}>
              🗑️ Hapus
            </button>
            )}
          </div>

          {/* Divider */}
          <div className="divider" />

          {/* Reviews */}
          <div className="reviews-section">
            <div className="reviews-header">
              <h3>⭐ Rating &amp; Ulasan Warga</h3>
              {avgRating > 0 && (
                <div className="avg-stars-big">
                  <span className="avg-num">{avgRating.toFixed(1)}</span>
                  <Stars rating={avgRating} size="md" />
                </div>
              )}
            </div>

            {loadingRev ? (
              <div style={{ padding: '20px', textAlign: 'center', color: 'var(--text-3)' }}>
                Memuat ulasan...
              </div>
            ) : reviews.length === 0 ? (
              <div style={{ padding: '16px', textAlign: 'center', color: 'var(--text-3)', fontSize: 13 }}>
                Belum ada ulasan. Jadilah yang pertama! 🎉
              </div>
            ) : (
              reviews.map(r => (
                <div key={r.id} className="review-card">
                  <div className="review-top">
                    <div className="review-avatar">
                      {r.nama_reviewer.charAt(0).toUpperCase()}
                    </div>
                    <div>
                      <div className="review-name">{r.nama_reviewer}</div>
                      {r.no_rumah_reviewer && (
                        <div className="review-house">🏠 {r.no_rumah_reviewer}</div>
                      )}
                    </div>
                    <Stars rating={r.rating} />
                    <span className="review-date">{(r.created_at || '').slice(0, 10)}</span>
                    <button className="review-del" onClick={() => handleDelReview(r.id)}>✕</button>
                  </div>
                  {r.komentar && (
                    <div className="review-comment">{r.komentar}</div>
                  )}
                </div>
              ))
            )}

            {/* Add review */}
            {!showForm ? (
              <button
                className="btn btn-secondary"
                style={{ marginTop: 12, width: '100%' }}
                onClick={() => setShowForm(true)}
              >
                ✍️ Tulis Ulasan
              </button>
            ) : (
              <div className="add-review-form">
                <h4>✍️ Tulis Ulasan Kamu</h4>
                <StarPicker value={revRating} onChange={setRevRating} />
                <div className="form-grid" style={{ marginBottom: 10 }}>
                  <div className="form-group">
                    <label className="form-label">Nama <span className="req">*</span></label>
                    <input
                      className="form-control"
                      value={revName}
                      onChange={e => setRevName(e.target.value)}
                      placeholder="Nama kamu"
                    />
                  </div>
                  <div className="form-group">
                    <label className="form-label">No. Rumah</label>
                    <input
                      className="form-control"
                      value={revHouse}
                      onChange={e => setRevHouse(e.target.value)}
                      placeholder="Cth: B-05"
                    />
                  </div>
                  <div className="form-group full">
                    <label className="form-label">Komentar</label>
                    <textarea
                      className="form-control"
                      value={revComment}
                      onChange={e => setRevComment(e.target.value)}
                      placeholder="Tulis pengalaman kamu..."
                      rows={3}
                    />
                  </div>
                </div>
                <div style={{ display: 'flex', gap: 8, justifyContent: 'flex-end' }}>
                  <button className="btn btn-secondary btn-sm" onClick={() => setShowForm(false)}>
                    Batal
                  </button>
                  <button
                    className="btn btn-primary btn-sm"
                    onClick={handleSubmitReview}
                    disabled={submitting}
                  >
                    {submitting ? 'Mengirim...' : '📤 Kirim Ulasan'}
                  </button>
                </div>
              </div>
            )}
          </div>
        </div>
      </div>
    </div>
  );
}
