import { useEffect, useState } from "react";

import { API_BASE_URL } from "@/config/api";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { toast } from "@/components/ui/sonner";
import { useAuth } from "@/contexts/AuthContext";

// Format number with dot separator (1000000 -> 1.000.000)
const formatJumlah = (value) => {
  if (!value) return "";
  return value.toString().replace(/\B(?=(\d{3})+(?!\d))/g, ".");
};

// Remove dot separator (1.000.000 -> 1000000)
const removeFormatting = (value) => {
  return value.replace(/\./g, "");
};

export default function KeuanganForm({ open, onOpenChange, transaksi, onSaved }) {
  const { token } = useAuth(); // 🔐 JWT
  const [loading, setLoading] = useState(false);
  const [categories, setCategories] = useState([]);

  const [form, setForm] = useState({
    tipe: "pemasukan",
    kategori: "",
    deskripsi: "",
    jumlah: 0,
    tanggal: "",
  });

  // --------------------------------------------------
  // LOAD CATEGORIES
  // --------------------------------------------------
  useEffect(() => {
    const loadCategories = async () => {
      try {
        const res = await fetch(`${API_BASE_URL}/api/finance-category`, {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });

        if (res.ok) {
          const data = await res.json();
          setCategories(data);
        }
      } catch (err) {
        console.error("Gagal load kategori", err);
      }
    };

    if (token) {
      loadCategories();
    }
  }, [token]);

  // --------------------------------------------------
  // LOAD DATA SAAT EDIT
  // --------------------------------------------------
  useEffect(() => {
    if (transaksi) {
      const tanggalStr = transaksi.tanggal ? transaksi.tanggal.split("T")[0] : "";
      setForm({
        tipe: transaksi.tipe || "pemasukan",
        kategori: transaksi.kategori || "",
        deskripsi: transaksi.deskripsi || "",
        jumlah: transaksi.jumlah || 0,
        tanggal: tanggalStr,
      });
    } else {
      setForm({
        tipe: "pemasukan",
        kategori: "",
        deskripsi: "",
        jumlah: 0,
        tanggal: new Date().toISOString().split("T")[0],
      });
    }
  }, [transaksi]);

  // --------------------------------------------------
  // SAVE
  // --------------------------------------------------
  const save = async () => {
    if (!form.kategori.trim()) {
      toast.error("Kategori harus diisi");
      return;
    }

    if (form.jumlah <= 0) {
      toast.error("Jumlah harus lebih dari 0");
      return;
    }

    setLoading(true);

    const url = transaksi
      ? `${API_BASE_URL}/api/keuangan/${transaksi.id}`
      : `${API_BASE_URL}/api/keuangan`;

    const method = transaksi ? "PUT" : "POST";

    try {
      const payload = {
        ...form,
        jumlah: parseFloat(form.jumlah),
        tanggal: new Date(form.tanggal).toISOString(),
      };

      const res = await fetch(url, {
        method,
        headers: {
          "Content-Type": "application/json",
          Authorization: `Bearer ${token}`,
        },
        body: JSON.stringify(payload),
      });

      if (!res.ok) {
        toast.error("Gagal menyimpan transaksi");
        setLoading(false);
        return;
      }

      toast.success(transaksi ? "Transaksi berhasil diperbarui!" : "Transaksi baru ditambahkan!");
      onSaved();
      onOpenChange(false);

    } catch (err) {
      toast.error("Tidak dapat terhubung ke server");
      console.error(err);
    }

    setLoading(false);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-md dark:bg-gray-900 dark:text-gray-100">
        <DialogHeader>
          <DialogTitle>{transaksi ? "Edit Transaksi" : "Tambah Transaksi"}</DialogTitle>
        </DialogHeader>

        <div className="space-y-4">

          {/* TIPE TRANSAKSI */}
          <div>
            <label className="block text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase mb-2">
              Tipe Transaksi
            </label>
            <select
              value={form.tipe}
              onChange={(e) => setForm({ ...form, tipe: e.target.value })}
              className="
                w-full p-2 rounded-md border
                border-gray-300 dark:border-gray-700
                bg-white dark:bg-gray-800
                text-gray-900 dark:text-gray-100
                focus:outline-none focus:ring-2 focus:ring-cyan-500
              "
            >
              <option value="pemasukan">Pemasukan</option>
              <option value="pengeluaran">Pengeluaran</option>
            </select>
          </div>

          {/* KATEGORI */}
          <div>
            <Label htmlFor="kategori" className="text-xs font-semibold uppercase">
              Kategori
            </Label>
            <Select value={form.kategori} onValueChange={(value) => setForm({ ...form, kategori: value })}>
              <SelectTrigger className="dark:bg-gray-800 dark:text-gray-100 dark:border-gray-700">
                <SelectValue placeholder="Pilih kategori" />
              </SelectTrigger>
              <SelectContent className="dark:bg-gray-800">
                {categories.length === 0 ? (
                  <div className="p-2 text-sm text-gray-500">Tidak ada kategori</div>
                ) : (
                  categories.map((cat) => (
                    <SelectItem key={cat.id} value={cat.id}>
                      {cat.nama} ({cat.tipe})
                    </SelectItem>
                  ))
                )}
              </SelectContent>
            </Select>
          </div>

          {/* DESKRIPSI */}
          <textarea
            placeholder="Deskripsi (opsional)"
            value={form.deskripsi}
            onChange={(e) => setForm({ ...form, deskripsi: e.target.value })}
            className="
              w-full p-2 rounded-md border
              border-gray-300 dark:border-gray-700
              bg-white dark:bg-gray-800
              text-gray-900 dark:text-gray-100
              focus:outline-none focus:ring-2 focus:ring-cyan-500
              min-h-20
            "
          />

          {/* JUMLAH */}
          <div>
            <label className="block text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase mb-2">
              Jumlah (Rp)
            </label>
            <Input
              type="text"
              placeholder="0"
              value={formatJumlah(form.jumlah)}
              onChange={(e) => {
                const rawValue = removeFormatting(e.target.value);
                setForm({ ...form, jumlah: rawValue || 0 });
              }}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* TANGGAL */}
          <div>
            <label className="block text-xs font-semibold text-gray-600 dark:text-gray-400 uppercase mb-2">
              Tanggal
            </label>
            <Input
              type="date"
              value={form.tanggal}
              onChange={(e) => setForm({ ...form, tanggal: e.target.value })}
              className="dark:bg-gray-800 dark:text-gray-100"
            />
          </div>

          {/* BUTTONS */}
          <div className="flex gap-3 justify-end pt-4">
            <Button
              variant="outline"
              onClick={() => onOpenChange(false)}
              className="dark:border-gray-700 dark:text-gray-200 dark:hover:bg-gray-800"
            >
              Batal
            </Button>
            <Button
              onClick={save}
              disabled={loading}
              className="bg-cyan-500 hover:bg-cyan-600 text-white"
            >
              {loading ? "Menyimpan..." : "Simpan"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}
